    <header className="sticky top-0 z-40 border-b border-border bg-background/95 backdrop-blur"><div className="mx-auto flex h-[76px] max-w-[1440px] items-center justify-between gap-5 px-5 sm:px-8 lg:px-12"><a href="#home" onClick={(event) => { event.preventDefault(); changePage("Home"); }} aria-label="Global CNC home"><Brand /></a><nav className="hidden items-center gap-6 xl:flex">{publicPages.slice(1, 7).map((page) => <button key={page} onClick={() => changePage(page)} className={`text-[12px] font-semibold transition-colors hover:text-industrial-orange ${publicPage === page ? "text-industrial-orange" : "text-foreground/75"}`}>{page}</button>)}</nav><div className="flex items-center gap-2"><Button variant="ghost" size="sm" className="hidden text-xs md:inline-flex" onClick={() => { setMode("admin"); setRole("Employee"); }}>{"Employee portal"}</Button><Button className="h-10 rounded-sm bg-industrial-orange px-4 text-xs text-primary-foreground hover:bg-industrial-orange/90" onClick={() => changePage("Contact")}>Request a quote <Icon name="arrow" size={15}/></Button><Button variant="ghost" size="icon" className="xl:hidden" aria-label="Open menu" onClick={() => setSidebarOpen(!sidebarOpen)}><Icon name="menu"/></Button></div></div>{sidebarOpen && <div className="border-t border-border px-5 py-3 xl:hidden"><div className="flex flex-wrap gap-x-5 gap-y-3">{publicPages.map((page) => <button key={page} onClick={() => { changePage(page); setSidebarOpen(false); }} className="text-xs font-semibold">{page}</button>)}<button className="text-xs font-semibold text-industrial-orange" onClick={() => { setMode("admin"); setRole("Employee"); }}>Employee portal</button></div></div>}</header>
