function Eyebrow({ children, light = false }: { children: ReactNode; light?: boolean }) { return <div className={`flex items-center gap-3 text-[10px] font-extrabold uppercase tracking-[0.19em] ${light ? "text-primary-foreground/65" : "text-steel-blue"}`}><span className="h-px w-7 bg-industrial-orange"/>{children}</div>; }

function PublicPage({ page, onNavigate }: { page: string; onNavigate: (page: string) => void }) {
  const pageCopy: Partial<Record<string, { title: string; desc: string }>> = {
    "About us": { title: "Engineering that starts with listening.", desc: "Global CNC Pvt. Ltd. partners with manufacturers to design, build and support machines that make production better." },
    Machines: { title: "The right machine for the work ahead.", desc: "From one-off special purpose machines to flexible CNC platforms, every solution starts with your application." },
    Services: { title: "Support from first install to every cycle after.", desc: "Practical service, planned maintenance and engineering expertise to keep your operation moving." },
    Industries: { title: "Precision for the industries that move us forward.", desc: "Purpose-built machinery for demanding applications across India's manufacturing economy." },
    Projects: { title: "Real production challenges. Thoughtful engineering.", desc: "A glimpse of the custom projects and production systems we engineer in partnership with our customers." },
    Gallery: { title: "Inside the work.", desc: "A look at our machining systems, engineered solutions and the people behind them." },
    Careers: { title: "Build what's next with us.", desc: "Join a team that values precision, curiosity and practical problem-solving on the factory floor." },
    Contact: { title: "Tell us what you need to make.", desc: "Talk with our engineering team about a new machine, a production challenge or ongoing service." },
  };
  const info = pageCopy[page] ?? { title: "Tell us what you need to make.", desc: "Talk with our engineering team about a new machine, a production challenge or ongoing service." };
  const [sent, setSent] = useState(false);
  const [form, setForm] = useState({ name: "", email: "", phone: "", message: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); setSent(true); setForm({ name: "", email: "", phone: "", message: "" }); };
  return <><section className="relative overflow-hidden bg-primary text-primary-foreground"><img src={factoryImage} alt="Global CNC machining capability" className="absolute inset-0 size-full object-cover opacity-35"/><div className="absolute inset-0 bg-gradient-to-r from-primary via-primary/90 to-primary/50"/><div className="relative mx-auto max-w-[1280px] px-5 py-20 sm:px-8 lg:px-10 lg:py-28"><div className="text-[10px] font-bold uppercase tracking-[0.2em] text-primary-foreground/65">Global CNC <span className="mx-2 text-industrial-orange">/</span> {page}</div><h1 className="mt-5 max-w-3xl text-4xl font-extrabold leading-tight sm:text-5xl">{info.title}</h1><p className="mt-5 max-w-2xl text-base leading-7 text-primary-foreground/75">{info.desc}</p>{page !== "Contact" && <Button className="mt-8 rounded-sm bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90" onClick={() => onNavigate("Contact")}>Talk with our team <Icon name="arrow" size={15}/></Button>}</div></section>
    {page === "Contact" ? <section className="mx-auto grid max-w-[1280px] gap-10 px-5 py-16 sm:px-8 lg:grid-cols-[0.85fr_1.15fr] lg:px-10"><div><Eyebrow>Get in touch</Eyebrow><h2 className="mt-4 text-3xl font-extrabold text-primary">Let's discuss your next project.</h2><p className="mt-4 text-sm leading-6 text-muted-foreground">Our team will help connect you to the right engineering or service expert.</p><div className="mt-8 space-y-5"><div><div className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Call our team</div><a href="tel:+918087696166" className="mt-1 block font-bold text-primary">+91 80876 96166</a></div><div><div className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Email us</div><a href="mailto:deventerprises1016@gmail.com" className="mt-1 block break-all font-bold text-primary">deventerprises1016@gmail.com</a></div><div><div className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Visit</div><p className="mt-1 max-w-sm text-sm leading-6 text-primary">{companyAddress}</p></div></div><div className="mt-7 flex aspect-[16/7] items-center justify-center border border-border bg-secondary text-center"><div><Icon name="building" size={26}/><p className="mt-2 text-xs font-bold">Bhosari, Pune · Maharashtra 411034</p><p className="mt-1 text-[10px] text-muted-foreground">Global CNC facility location</p></div></div></div><form className="border border-border bg-card p-6 sm:p-8" onSubmit={submit}><h3 className="text-xl font-bold text-primary">Send an enquiry</h3><p className="mt-1 text-xs text-muted-foreground">Tell us a little about what you need.</p>{sent && <div className="mt-4 border border-steel-blue/30 bg-secondary px-4 py-3 text-sm font-semibold text-primary">Thank you. Your enquiry has been noted for our team.</div>}<div className="mt-6 grid gap-4 sm:grid-cols-2">{([["name", "Your name", "text"], ["email", "Work email", "email"], ["phone", "Phone number", "tel"]] as const).map(([key, label, type]) => <label key={key} className="grid gap-2 text-xs font-semibold text-primary">{label}<input required={key !== "phone"} type={type} value={form[key]} onChange={(event) => setForm({ ...form, [key]: event.target.value })} className="h-11 border border-input bg-background px-3 text-sm font-normal outline-none focus:border-steel-blue" /></label>)}<label className="grid gap-2 text-xs font-semibold text-primary sm:col-span-2">How can we help?<textarea required value={form.message} onChange={(event) => setForm({ ...form, message: event.target.value })} rows={5} className="border border-input bg-background px-3 py-3 text-sm font-normal outline-none focus:border-steel-blue" placeholder="Machine type, component, production target or service need"/></label></div><Button type="submit" className="mt-5 h-11 rounded-sm bg-industrial-orange px-5 text-primary-foreground hover:bg-industrial-orange/90">Send enquiry <Icon name="arrow" size={14}/></Button><p className="mt-3 text-[10px] text-muted-foreground">Demo enquiry form. Submitted details are not sent to a server.</p></form></section> : <section className="mx-auto max-w-[1280px] px-5 py-14 sm:px-8 lg:px-10"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{(page === "Machines" ? machineCards.map((item) => ({ title: item.name, desc: item.text, label: item.tag })) : page === "Services" ? services.map((item) => ({ title: item, desc: "Application-led support, delivered with an experienced engineering and service team.", label: "GLOBAL CNC SERVICE" })) : page === "Industries" ? industries.map((item) => ({ title: item, desc: "Precision machines and integrated production solutions for demanding industrial applications.", label: "INDUSTRY CAPABILITY" })) : page === "Careers" ? ["Mechanical design", "CNC programming", "Electrical engineering", "Field service", "Production and quality", "Business development"].map((item) => ({ title: item, desc: "Bring your experience, ideas and attention to detail to our growing engineering team.", label: "CAREER PATH" })) : (datasets["projects"].slice(0, 6)).map((item) => ({ title: String(item.name), desc: `A collaborative ${item.category.toLowerCase()} project designed for repeatable quality and production flow.`, label: "ENGINEERED PROJECT" }))).map((item, index) => <article key={`${item.title}-${index}`} className="border border-border bg-card p-5"><div className="flex size-10 items-center justify-center bg-secondary text-steel-blue"><Icon name={page === "Services" ? "wrench" : "machine"}/></div><p className="mt-5 text-[9px] font-bold uppercase tracking-wider text-industrial-orange">{item.label}</p><h2 className="mt-2 text-lg font-bold text-primary">{item.title}</h2><p className="mt-2 text-xs leading-5 text-muted-foreground">{item.desc}</p></article>)}</div><div className="mt-12 flex flex-wrap items-center justify-between gap-4 border-t border-border pt-8"><p className="text-sm font-bold text-primary">Have a requirement you don't see here?</p><Button className="rounded-sm bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90" onClick={() => onNavigate("Contact")}>Talk to an engineer <Icon name="arrow" size={15}/></Button></div></section>}</>;
}

function LoginPage({ role, setRole, onBack, onLogin }: { role: "Admin" | "Employee"; setRole: (role: "Admin" | "Employee") => void; onBack: () => void; onLogin: () => void }) {
  return <main className="grid min-h-screen bg-background lg:grid-cols-[1.05fr_0.95fr]"><div className="relative hidden overflow-hidden bg-primary lg:block"><img src={factoryImage} alt="CNC machine on a factory floor" className="absolute inset-0 size-full object-cover opacity-45"/><div className="absolute inset-0 bg-gradient-to-t from-primary via-primary/65 to-primary/15"/><div className="relative flex h-full flex-col justify-between p-12 text-primary-foreground"><Brand inverse/><div className="max-w-xl pb-8"><Eyebrow light>Global CNC · operations</Eyebrow><h1 className="mt-5 text-5xl font-extrabold leading-tight">A clearer view<br/>of every operation.</h1><p className="mt-5 max-w-md text-sm leading-6 text-primary-foreground/75">Manage sales, production, inventory and service from one connected workspace.</p></div><p className="text-xs text-primary-foreground/55">GLOBAL CNC PVT. LTD. · PUNE, INDIA</p></div></div><div className="flex min-h-screen flex-col"><div className="flex items-center justify-between border-b border-border px-5 py-5 sm:px-10"><Brand/><Button variant="ghost" size="sm" onClick={onBack}>Back to website</Button></div><div className="flex flex-1 items-center justify-center px-5 py-10"><div className="w-full max-w-[420px]"><Eyebrow>Secure team access</Eyebrow><h2 className="mt-4 text-3xl font-extrabold text-primary">Welcome back.</h2><p className="mt-2 text-sm text-muted-foreground">Sign in to your operations workspace.</p><RolePicker role={role} setRole={setRole}/><form className="mt-6 space-y-4" onSubmit={(event) => { event.preventDefault(); onLogin(); }}><label className="grid gap-2 text-xs font-semibold">Work email<input type="email" required defaultValue={role === "Admin" ? "admin@globalcnc.in" : "employee@globalcnc.in"} className="h-11 border border-input bg-card px-3 text-sm font-normal outline-none focus:border-steel-blue"/></label><label className="grid gap-2 text-xs font-semibold">Password<input type="password" required defaultValue="globalcnc" className="h-11 border border-input bg-card px-3 text-sm font-normal outline-none focus:border-steel-blue"/></label><Button type="submit" className="h-11 w-full rounded-sm bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90">Sign in to workspace <Icon name="arrow" size={15}/></Button></form><div className="mt-5 border border-border bg-secondary/60 p-4"><div className="text-xs font-bold text-primary">Demo access</div><div className="mt-2 grid grid-cols-2 gap-3 text-[11px] text-muted-foreground"><div><span className="block font-semibold text-primary">Admin</span>admin@globalcnc.in</div><div><span className="block font-semibold text-primary">Employee</span>employee@globalcnc.in</div><div className="col-span-2">Password: <span className="font-semibold text-primary">globalcnc</span></div></div></div><p className="mt-5 text-center text-[10px] text-muted-foreground">Local demonstration only. No account or password is sent anywhere.</p></div></div></div></main>;
}
function RolePicker({ role, setRole }: { role: "Admin" | "Employee"; setRole: (role: "Admin" | "Employee") => void }) { return <div className="mt-6 grid grid-cols-2 border border-border p-1">{(["Admin", "Employee"] as const).map((item) => <Button key={item} variant={role === item ? "default" : "ghost"} className={`h-9 rounded-sm text-xs ${role === item ? "bg-primary text-primary-foreground" : "text-muted-foreground"}`} onClick={() => setRole(item)}>{item}</Button>)}</div>; }
function LoginDialog({ onClose, onLogin }: { onClose: () => void; onLogin: (role: "Admin" | "Employee") => void }) { const [role, setRole] = useState<"Admin" | "Employee">("Admin"); return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-primary/70 p-4" onClick={onClose}><div className="w-full max-w-md bg-card p-6 shadow-xl" onClick={(event) => event.stopPropagation()}><div className="flex items-center justify-between"><Brand/><Button variant="ghost" size="icon" aria-label="Close" onClick={onClose}><Icon name="close"/></Button></div><div className="mt-7"><Eyebrow>Team portal</Eyebrow><h2 className="mt-3 text-2xl font-extrabold text-primary">Sign in to operations</h2><RolePicker role={role} setRole={setRole}/><form onSubmit={(event) => { event.preventDefault(); onLogin(role); }} className="mt-5 space-y-3"><input aria-label="Work email" type="email" required defaultValue={role === "Admin" ? "admin@globalcnc.in" : "employee@globalcnc.in"} className="h-11 w-full border border-input bg-background px-3 text-sm outline-none focus:border-steel-blue"/><input aria-label="Password" type="password" required defaultValue="globalcnc" className="h-11 w-full border border-input bg-background px-3 text-sm outline-none focus:border-steel-blue"/><Button type="submit" className="w-full rounded-sm bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90">Continue <Icon name="arrow" size={14}/></Button></form><p className="mt-4 text-center text-[10px] text-muted-foreground">Demo: admin@globalcnc.in / globalcnc</p></div></div></div>; }

function AdminWorkspace({ active, setActive, onSignOut, dark, setDark, sidebarOpen, setSidebarOpen }: { active: ModuleKey | "dashboard"; setActive: (key: ModuleKey | "dashboard") => void; onSignOut: () => void; dark: boolean; setDark: (value: boolean) => void; sidebarOpen: boolean; setSidebarOpen: (value: boolean) => void }) {
  const [profileOpen, setProfileOpen] = useState(false);
  const [notice, setNotice] = useState("");
  const [recordOverrides, setRecordOverrides] = useState<Partial<Record<ModuleKey, RecordRow[]>>>({});
  const [toast, setToast] = useState("");
  const selected = allNav.find((item) => item.key === active);
  const currentTitle = active === "dashboard" ? "Dashboard" : selected?.label ?? "Dashboard";
  const records = active === "dashboard" ? [] : (recordOverrides[active] ?? datasets[active] ?? []) as RecordRow[];
  const update = (next: RecordRow[]) => setRecordOverrides({ ...recordOverrides, [active as ModuleKey]: next });
  const flash = (text: string) => { setToast(text); setTimeout(() => setToast(""), 2800); };
  return <div className={dark ? "dark" : ""}><div className="flex h-screen min-h-[640px] overflow-hidden bg-background text-foreground"><aside className={`fixed inset-y-0 left-0 z-50 flex w-[254px] flex-col bg-primary text-primary-foreground transition-transform lg:static lg:translate-x-0 ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}><div className="flex h-[72px] items-center justify-between border-b border-primary-foreground/10 px-5"><Brand inverse/><Button variant="ghost" size="icon" className="text-primary-foreground lg:hidden" aria-label="Close menu" onClick={() => setSidebarOpen(false)}><Icon name="close"/></Button></div><div className="border-b border-primary-foreground/10 px-5 py-4"><div className="text-[9px] font-bold uppercase tracking-[0.18em] text-primary-foreground/45">Workspace</div><div className="mt-2 flex items-center justify-between"><span className="text-xs font-semibold">Global CNC · Pune</span><Icon name="down" size={14}/></div></div><nav className="flex-1 overflow-y-auto px-3 py-4">{groups.map((group) => <div key={group.label} className="mb-5"><div className="mb-2 px-2 text-[9px] font-bold uppercase tracking-[0.18em] text-primary-foreground/40">{group.label}</div><div className="space-y-0.5">{group.items.map((item) => <button key={item.key} onClick={() => { setActive(item.key); setSidebarOpen(false); }} className={`flex h-9 w-full items-center gap-3 px-2.5 text-left text-[11px] font-semibold transition-colors ${active === item.key ? "bg-sidebar-accent text-primary-foreground" : "text-primary-foreground/65 hover:bg-sidebar-accent/70 hover:text-primary-foreground"}`}><Icon name={item.icon} size={15}/><span className="flex-1">{item.label}</span>{item.key === "inventory" && <span className="size-1.5 rounded-full bg-industrial-orange"/>}</button>)}</div></div>)}</nav><div className="border-t border-primary-foreground/10 p-3"><button className="flex w-full items-center gap-3 px-2 py-2 text-left hover:bg-sidebar-accent" onClick={() => { setProfileOpen(false); setActive("settings"); }}><div className="flex size-8 items-center justify-center bg-industrial-orange text-xs font-bold text-primary">AS</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">Aarav Sharma</div><div className="text-[10px] text-primary-foreground/55">Administrator</div></div><Icon name="down" size={13}/></button></div></aside>
    {sidebarOpen && <button aria-label="Close navigation" className="fixed inset-0 z-40 bg-primary/40 lg:hidden" onClick={() => setSidebarOpen(false)}/>}
    <section className="flex min-w-0 flex-1 flex-col"><header className="relative z-20 flex h-[72px] shrink-0 items-center justify-between border-b border-border bg-card px-4 sm:px-7"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="lg:hidden" aria-label="Open navigation" onClick={() => setSidebarOpen(true)}><Icon name="menu"/></Button><div><div className="hidden text-[10px] text-muted-foreground sm:block">Workspace <span className="mx-1">/</span> {currentTitle}</div><div className="text-base font-extrabold text-primary">{currentTitle}</div></div></div><div className="flex items-center gap-1 sm:gap-2"><label className="hidden h-9 items-center gap-2 border border-border bg-background px-2.5 md:flex"><Icon name="search" size={15}/><input className="w-36 bg-transparent text-[11px] outline-none placeholder:text-muted-foreground" placeholder="Search workspace" onChange={(event) => { if (active !== "dashboard") setNotice(event.target.value); }}/><kbd className="text-[9px] text-muted-foreground">⌘ K</kbd></label><Button variant="ghost" size="icon" aria-label="Toggle dark mode" title="Toggle dark mode" onClick={() => setDark(!dark)}><Icon name="moon" size={17}/></Button><div className="relative"><Button variant="ghost" size="icon" aria-label="Notifications" onClick={() => setNotice(notice ? "" : "notifications")}><Icon name="bell" size={17}/><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-industrial-orange"/></Button>{notice === "notifications" && <div className="absolute right-0 top-11 w-[300px] border border-border bg-card p-4 shadow-xl"><div className="font-bold text-primary">Notifications <span className="ml-2 bg-secondary px-1.5 py-0.5 text-[10px]">3</span></div>{activitiesData.slice(0, 3).map((activity) => <div key={activity.text} className="border-b border-border py-3 text-xs leading-5">{activity.text}<div className="text-[10px] text-muted-foreground">{activity.time}</div></div>)}</div>}</div><div className="relative"><Button variant="ghost" size="sm" className="gap-2 px-1.5" onClick={() => setProfileOpen(!profileOpen)}><span className="flex size-8 items-center justify-center bg-secondary text-xs font-bold text-primary">AS</span><span className="hidden text-xs font-semibold sm:inline">Aarav Sharma</span><Icon name="down" size={13}/></Button>{profileOpen && <div className="absolute right-0 top-11 w-44 border border-border bg-card p-1 shadow-xl"><button onClick={onSignOut} className="w-full px-3 py-2 text-left text-xs font-semibold hover:bg-secondary">Sign out</button></div>}</div></div></header>
    <main className="flex-1 overflow-y-auto"><div className="mx-auto max-w-[1440px] p-4 sm:p-7 lg:p-8">{active === "dashboard" ? <Dashboard onOpen={(key) => setActive(key)} flash={flash}/> : <RecordsView key={active} active={active} title={currentTitle} records={records} onUpdate={update} flash={flash}/>}</div></main></section></div>{toast && <div className="fixed bottom-5 right-5 z-[80] border border-border bg-card px-4 py-3 text-sm shadow-lg">{toast}</div>}</div>;
}

function Dashboard({ onOpen, flash }: { onOpen: (key: ModuleKey) => void; flash: (text: string) => void }) {
  const kpis = [{ title: "Today's sales", value: "₹8.42L", delta: "+12.8%", icon: "trend", color: "text-steel-blue", key: "sales" as const }, { title: "Monthly revenue", value: "₹1.84Cr", delta: "+8.2%", icon: "wallet", color: "text-industrial-orange", key: "accounting" as const }, { title: "Pending orders", value: "24", delta: "6 need review", icon: "cart", color: "text-steel-blue", key: "sales" as const }, { title: "Open service calls", value: "07", delta: "2 priority", icon: "wrench", color: "text-industrial-orange", key: "services" as const }];
  const bars = [32, 45, 39, 60, 47, 72, 56, 68, 52, 80, 64, 92];
  return <div className="space-y-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="text-[10px] font-semibold text-muted-foreground">Wednesday, 19 November 2026 <span className="mx-1">·</span> Bhosari, Pune</div><h1 className="mt-2 text-2xl font-extrabold tracking-tight text-primary sm:text-3xl">Good morning, Aarav <span className="text-industrial-orange">.</span></h1><p className="mt-1 text-xs text-muted-foreground">Here’s your operation at a glance.</p></div><div className="flex gap-2"><Button variant="outline" size="sm" className="rounded-sm text-xs" onClick={() => flash("Report export is a local demo placeholder.")}><Icon name="download" size={14}/> Export</Button><Button size="sm" className="rounded-sm bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90" onClick={() => onOpen("sales")}><Icon name="plus" size={14}/> New order</Button></div></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{kpis.map((kpi) => <button key={kpi.title} onClick={() => onOpen(kpi.key)} className="border border-border bg-card p-4 text-left transition-colors hover:border-steel-blue/50"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-muted-foreground">{kpi.title}</span><span className={kpi.color}><Icon name={kpi.icon} size={17}/></span></div><div className="mt-3 flex items-end justify-between"><span className="text-2xl font-extrabold text-primary">{kpi.value}</span><span className="text-[10px] font-semibold text-steel-blue">{kpi.delta}</span></div></button>)}</div>
    <div className="grid gap-4 xl:grid-cols-[1.55fr_1fr]"><section className="border border-border bg-card p-4 sm:p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-extrabold text-primary">Revenue overview</h2><p className="mt-1 text-[10px] text-muted-foreground">Sales performance · last 12 months</p></div><select className="h-8 border border-input bg-background px-2 text-[10px] text-muted-foreground"><option>2026</option><option>2025</option></select></div><div className="relative mt-6 h-[190px] border-b border-l border-border px-3"><div className="absolute inset-0 flex flex-col justify-between pb-0">{[0, 1, 2, 3].map((line) => <div key={line} className="w-full border-t border-dashed border-border"/>)}</div><div className="relative flex h-full items-end justify-between gap-2">{bars.map((bar, index) => <div key={index} className="flex h-full flex-1 flex-col items-center justify-end"><div className={`w-full max-w-8 transition-all ${index === bars.length - 1 ? "bg-industrial-orange" : "bg-steel-blue/70 hover:bg-steel-blue"}`} style={{ height: `${bar}%` }}/><span className="absolute mt-2 translate-y-5 text-[8px] text-muted-foreground">{["D", "J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N"][index]}</span></div>)}</div></div><div className="mt-8 flex items-center gap-4 text-[9px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="size-2 bg-steel-blue"/>Sales revenue</span><span className="flex items-center gap-1.5"><i className="size-2 bg-industrial-orange"/>Current month</span><span className="ml-auto font-bold text-primary">₹1.84Cr <span className="font-normal text-muted-foreground">this month</span></span></div></section>
    <section className="border border-border bg-card p-4 sm:p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-extrabold text-primary">Order pipeline</h2><p className="mt-1 text-[10px] text-muted-foreground">Current sales order status</p></div><Button variant="ghost" size="sm" className="text-[10px] text-steel-blue" onClick={() => onOpen("sales")}>View all <Icon name="arrow" size={12}/></Button></div><div className="mt-5 space-y-4">{[{ label: "In progress", value: 47, count: 24, className: "bg-steel-blue" }, { label: "Awaiting approval", value: 22, count: 11, className: "bg-industrial-orange" }, { label: "Completed", value: 68, count: 35, className: "bg-primary" }, { label: "On hold", value: 13, count: 7, className: "bg-muted-foreground" }].map((item) => <div key={item.label}><div className="mb-1.5 flex justify-between text-[10px]"><span className="font-semibold text-primary">{item.label}</span><span className="text-muted-foreground">{item.count} orders</span></div><div className="h-1.5 bg-secondary"><div className={`h-full ${item.className}`} style={{ width: `${item.value}%` }}/></div></div>)}</div><div className="mt-6 border-t border-border pt-4"><div className="flex justify-between text-xs"><span className="text-muted-foreground">Total active orders</span><span className="font-extrabold text-primary">77</span></div></div></section></div>
    <div className="grid gap-4 xl:grid-cols-[1.35fr_1fr]"><section className="border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-4 py-4 sm:px-5"><div><h2 className="text-sm font-extrabold text-primary">Recent orders</h2><p className="mt-1 text-[10px] text-muted-foreground">Latest sales activity across the team</p></div><Button variant="ghost" size="sm" className="text-[10px] text-steel-blue" onClick={() => onOpen("sales")}>See all <Icon name="arrow" size={12}/></Button></div><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-[10px]"><thead className="bg-secondary/50 text-[9px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-4 py-3 font-bold">Order</th><th className="px-4 py-3 font-bold">Customer</th><th className="px-4 py-3 font-bold">Date</th><th className="px-4 py-3 font-bold">Amount</th><th className="px-4 py-3 font-bold">Status</th></tr></thead><tbody>{datasets["sales"].slice(0, 5).map((item) => <tr key={item.id} className="border-t border-border"><td className="px-4 py-3 font-bold text-steel-blue">{item.reference}</td><td className="max-w-[180px] truncate px-4 py-3 font-semibold text-primary">{item.name}</td><td className="px-4 py-3 text-muted-foreground">{item.date}</td><td className="px-4 py-3 font-semibold text-primary">{money(item.amount)}</td><td className="px-4 py-3"><StatusBadge status={item.status}/></td></tr>)}</tbody></table></div></section>
    <section className="border border-border bg-card"><div className="border-b border-border px-4 py-4 sm:px-5"><h2 className="text-sm font-extrabold text-primary">Recent activity</h2><p className="mt-1 text-[10px] text-muted-foreground">Latest updates across the workspace</p></div><div className="divide-y divide-border px-4 sm:px-5">{activitiesData.map((item) => <div key={item.text} className="flex gap-3 py-3.5"><div className={`flex size-8 shrink-0 items-center justify-center text-[9px] font-extrabold ${item.tone === "orange" ? "bg-industrial-orange/10 text-industrial-orange" : item.tone === "green" ? "bg-steel-blue/10 text-steel-blue" : item.tone === "red" ? "bg-destructive/10 text-destructive" : "bg-secondary text-steel-blue"}`}>{item.initials}</div><div className="min-w-0 flex-1"><p className="text-[10px] leading-4 text-primary">{item.text}</p><p className="mt-1 text-[9px] text-muted-foreground">{item.time}</p></div></div>)}</div></section></div>
    <section className="grid gap-3 sm:grid-cols-3">{[{ title: "Inventory attention", count: "12 items", text: "Below minimum stock", icon: "boxes", key: "inventory" as const }, { title: "Open leads", count: "30 leads", text: "8 follow-ups due today", icon: "target", key: "leads" as const }, { title: "Projects on track", count: "21 / 25", text: "Across 6 active teams", icon: "folder", key: "projects" as const }].map((item) => <button key={item.title} onClick={() => onOpen(item.key)} className="flex items-center gap-4 border border-border bg-card p-4 text-left hover:border-steel-blue/50"><span className="flex size-10 items-center justify-center bg-secondary text-steel-blue"><Icon name={item.icon}/></span><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2 text-xs font-bold text-primary"><span>{item.title}</span><span className="text-steel-blue">{item.count}</span></span><span className="mt-1 block text-[10px] text-muted-foreground">{item.text}</span></span><Icon name="arrow" size={14}/></button>)}</section></div>;
}

function StatusBadge({ status }: { status: string }) {
  const positive = ["Approved", "Completed", "Active", "Preferred"].includes(status);
  const warm = ["Pending", "In progress", "Review", "On hold"].includes(status);
  return <span className={`inline-flex items-center gap-1.5 whitespace-nowrap px-2 py-1 text-[9px] font-bold ${positive ? "bg-steel-blue/10 text-steel-blue" : warm ? "bg-industrial-orange/10 text-industrial-orange" : "bg-secondary text-muted-foreground"}`}><span className={`size-1 rounded-full ${positive ? "bg-steel-blue" : warm ? "bg-industrial-orange" : "bg-muted-foreground"}`}/>{status}</span>;
}

function RecordsView({ active, title, records, onUpdate, flash }: { active: ModuleKey; title: string; records: RecordRow[]; onUpdate: (records: RecordRow[]) => void; flash: (text: string) => void }) {
  const [query, setQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("All statuses");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [sort, setSort] = useState<"date" | "amount">("date");
  const [sortDir, setSortDir] = useState<"asc" | "desc">("desc");
  const [modal, setModal] = useState<"create" | "view" | "edit" | null>(null);
  const [current, setCurrent] = useState<RecordRow | null>(null);
  const [draft, setDraft] = useState({ name: "", category: "", amount: "", status: "Pending", owner: "Aarav Kulkarni" });
  const statuses = ["All statuses", ...new Set(records.map((item) => item.status))];
  const filtered = useMemo(() => records.filter((item) => `${item.name} ${item.reference} ${item.category} ${item.owner} ${String(item["email"] ?? "")}`.toLowerCase().includes(query.toLowerCase()) && (statusFilter === "All statuses" || item.status === statusFilter)).slice().sort((a, b) => {
    const first = sort === "date" ? String(a.date) : Number(a.amount);
    const second = sort === "date" ? String(b.date) : Number(b.amount);
    return (first < second ? -1 : first > second ? 1 : 0) * (sortDir === "asc" ? 1 : -1);
  }), [records, query, statusFilter, sort, sortDir]);
  const pages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const shown = filtered.slice((page - 1) * pageSize, page * pageSize);
  const create = () => { setCurrent(null); setDraft({ name: "", category: "", amount: "", status: "Pending", owner: "Aarav Kulkarni" }); setModal("create"); };
  const edit = (record: RecordRow) => { setCurrent(record); setDraft({ name: record.name, category: record.category, amount: String(record.amount), status: record.status, owner: record.owner }); setModal("edit"); };
  const submit = (event: FormEvent) => { event.preventDefault(); const nextId = Math.max(...records.map((item) => item.id), 0) + 1; const changed: RecordRow = { ...(current ?? { id: nextId, date: new Date().toISOString().slice(0, 10), reference: `${active.slice(0, 3).toUpperCase()}-${String(nextId).padStart(4, "0")}` }), ...draft, amount: Number(draft.amount) || 0, id: current?.id ?? nextId }; if (current) onUpdate(records.map((item) => item.id === current.id ? changed : item)); else onUpdate([changed, ...records]); flash(current ? "Record updated." : "New record added."); setModal(null); };
  const remove = (record: RecordRow) => { if (window.confirm(`Remove ${record.name}?`)) { onUpdate(records.filter((item) => item.id !== record.id)); flash("Record removed."); } };
  const primaryAction = active === "reports" || active === "settings" ? active === "reports" ? "Export report" : "Edit settings" : `New ${active === "sales" ? "order" : active === "purchases" ? "purchase" : active === "leads" ? "lead" : active === "services" ? "ticket" : active === "customers" ? "customer" : active === "projects" ? "project" : active === "products" ? "product" : active === "expenses" ? "expense" : "record"}`;
  const fields = [{ label: "Name", value: "name" }, { label: "Category", value: "category" }, { label: "Status", value: "status" }, { label: "Date", value: "date" }, { label: "Amount", value: "amount" }, { label: "Owner", value: "owner" }] as const;
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="text-[10px] text-muted-foreground">Workspace <span className="mx-1">/</span> {title}</div><h1 className="mt-2 text-2xl font-extrabold text-primary">{title}</h1><p className="mt-1 text-xs text-muted-foreground">Manage and review {title.toLowerCase()} across Global CNC.</p></div><div className="flex gap-2"><Button variant="outline" size="sm" className="rounded-sm text-xs" onClick={() => flash("Export is a local demo placeholder.")}><Icon name="download" size={14}/> Export</Button><Button size="sm" className="rounded-sm bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90" onClick={() => active === "reports" || active === "settings" ? flash(`${primaryAction} is a local demo placeholder.`) : create()}><Icon name="plus" size={14}/>{primaryAction}</Button></div></div>
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{[{ label: "Total records", value: records.length.toLocaleString("en-IN") }, { label: "In progress", value: records.filter((item) => item.status === "In progress").length }, { label: "Pending review", value: records.filter((item) => item.status === "Pending").length }, { label: "Total value", value: money(records.reduce((sum, item) => sum + (Number(item.amount) || 0), 0)) }].map((item) => <div key={item.label} className="border border-border bg-card p-3.5"><div className="text-[10px] font-semibold text-muted-foreground">{item.label}</div><div className="mt-2 truncate text-lg font-extrabold text-primary">{item.value}</div></div>)}</div>
    <section className="border border-border bg-card"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border p-3.5"><div className="flex h-9 min-w-[180px] flex-1 items-center gap-2 border border-input bg-background px-2.5 sm:max-w-[330px]"><Icon name="search" size={14}/><input aria-label={`Search ${title}`} className="min-w-0 flex-1 bg-transparent text-xs outline-none placeholder:text-muted-foreground" placeholder={`Search ${title.toLowerCase()}...`} value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }}/>{query && <button onClick={() => setQuery("")} aria-label="Clear search"><Icon name="close" size={13}/></button>}</div><div className="flex items-center gap-2"><select aria-label="Filter by status" className="h-9 max-w-[145px] border border-input bg-background px-2 text-[10px]" value={statusFilter} onChange={(event) => { setStatusFilter(event.target.value); setPage(1); }}>{statuses.map((status) => <option key={status}>{status}</option>)}</select><Button variant="outline" size="sm" className="h-9 rounded-sm px-2.5 text-[10px]" onClick={() => { setSort(sort === "date" ? "amount" : "date"); setSortDir(sortDir === "asc" ? "desc" : "asc"); }}>Sort: {sort === "date" ? "Date" : "Amount"} <Icon name="down" size={12}/></Button></div></div>
    <div className="overflow-x-auto"><table className="w-full min-w-[820px] text-left text-[10px]"><thead className="bg-secondary/50 text-[9px] uppercase tracking-wider text-muted-foreground"><tr><th className="w-10 px-4 py-3"><input type="checkbox" aria-label="Select all visible records" className="accent-steel-blue"/></th><th className="px-3 py-3 font-bold">Record</th><th className="px-3 py-3 font-bold">Category</th><th className="px-3 py-3 font-bold">Date</th><th className="px-3 py-3 font-bold">Owner</th><th className="px-3 py-3 font-bold">Amount</th><th className="px-3 py-3 font-bold">Status</th><th className="px-3 py-3 text-right font-bold">Actions</th></tr></thead><tbody>{shown.map((item) => <tr key={item.id} className="border-t border-border transition-colors hover:bg-secondary/40"><td className="px-4 py-3"><input type="checkbox" aria-label={`Select ${item.name}`} className="accent-steel-blue"/></td><td className="max-w-[240px] px-3 py-3"><button className="block max-w-full truncate text-left font-bold text-primary hover:text-steel-blue" onClick={() => { setCurrent(item); setModal("view"); }}>{item.name}</button><span className="mt-1 block text-[9px] text-muted-foreground">{item.reference}</span></td><td className="px-3 py-3 text-muted-foreground">{item.category}</td><td className="px-3 py-3 text-muted-foreground">{item.date}</td><td className="px-3 py-3 text-primary">{item.owner}</td><td className="px-3 py-3 font-semibold text-primary">{Number(item.amount) ? money(Number(item.amount)) : "—"}</td><td className="px-3 py-3"><StatusBadge status={item.status}/></td><td className="px-3 py-3"><div className="flex justify-end gap-1"><Button variant="ghost" size="icon" className="size-7" aria-label={`Edit ${item.name}`} title="Edit" onClick={() => edit(item)}><Icon name="edit" size={13}/></Button><Button variant="ghost" size="icon" className="size-7 text-destructive" aria-label={`Delete ${item.name}`} title="Delete" onClick={() => remove(item)}><Icon name="trash" size={13}/></Button></div></td></tr>)}</tbody></table>{shown.length === 0 && <div className="px-5 py-16 text-center"><div className="mx-auto flex size-11 items-center justify-center bg-secondary text-muted-foreground"><Icon name="search" size={20}/></div><div className="mt-3 text-sm font-bold text-primary">No records found</div><div className="mt-1 text-xs text-muted-foreground">Try changing your search or status filter.</div></div>}</div>
    <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-4 py-3"><div className="text-[10px] text-muted-foreground">Showing <span className="font-semibold text-primary">{filtered.length ? (page - 1) * pageSize + 1 : 0}–{Math.min(page * pageSize, filtered.length)}</span> of <span className="font-semibold text-primary">{filtered.length}</span> records</div><div className="flex items-center gap-1.5"><label className="mr-2 flex items-center gap-1 text-[10px] text-muted-foreground">Rows <select className="h-7 border border-input bg-background px-1.5 text-[10px]" value={pageSize} onChange={(event) => { setPageSize(Number(event.target.value)); setPage(1); }}>{[10, 20, 50].map((value) => <option key={value}>{value}</option>)}</select></label><Button variant="outline" size="icon" className="size-7" aria-label="Previous page" disabled={page <= 1} onClick={() => setPage(page - 1)}>‹</Button><span className="min-w-12 text-center text-[10px] font-semibold">{page} / {pages}</span><Button variant="outline" size="icon" className="size-7" aria-label="Next page" disabled={page >= pages} onClick={() => setPage(page + 1)}>›</Button></div></div></section>
    {modal && current && modal === "view" ? <div className="fixed inset-0 z-[70] flex items-center justify-center bg-primary/60 p-4" onClick={() => setModal(null)}><div className="w-full max-w-lg border border-border bg-card p-6 shadow-xl" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between"><div><div className="text-[9px] font-bold uppercase tracking-wider text-steel-blue">{current.reference}</div><h2 className="mt-2 text-xl font-extrabold text-primary">{current.name}</h2></div><Button variant="ghost" size="icon" aria-label="Close details" onClick={() => setModal(null)}><Icon name="close"/></Button></div><div className="mt-5 grid grid-cols-2 gap-4">{fields.map((field) => <div key={field.value} className="border-t border-border pt-3"><div className="text-[9px] font-bold uppercase tracking-wider text-muted-foreground">{field.label}</div><div className="mt-1 text-xs font-semibold text-primary">{field.value === "amount" ? money(Number(current.amount)) : String(current[field.value] ?? "—")}</div></div>)}</div><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={() => setModal(null)}>Close</Button><Button className="bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90" onClick={() => edit(current)}>Edit record <Icon name="edit" size={14}/></Button></div></div></div> : null}
    {(modal === "create" || modal === "edit") && <div className="fixed inset-0 z-[70] flex items-center justify-center bg-primary/60 p-4" onClick={() => setModal(null)}><form className="w-full max-w-lg border border-border bg-card p-6 shadow-xl" onSubmit={submit} onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between"><div><div className="text-[9px] font-bold uppercase tracking-wider text-steel-blue">{modal === "create" ? "New entry" : "Update entry"}</div><h2 className="mt-2 text-xl font-extrabold text-primary">{modal === "create" ? primaryAction : "Edit record"}</h2></div><Button type="button" variant="ghost" size="icon" aria-label="Close form" onClick={() => setModal(null)}><Icon name="close"/></Button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="grid gap-1.5 text-[10px] font-bold">Name<input autoFocus required value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} className="h-10 border border-input bg-background px-3 text-xs font-normal outline-none focus:border-steel-blue"/></label><label className="grid gap-1.5 text-[10px] font-bold">Category<input value={draft.category} onChange={(event) => setDraft({ ...draft, category: event.target.value })} className="h-10 border border-input bg-background px-3 text-xs font-normal outline-none focus:border-steel-blue"/></label><label className="grid gap-1.5 text-[10px] font-bold">Amount (₹)<input type="number" min="0" value={draft.amount} onChange={(event) => setDraft({ ...draft, amount: event.target.value })} className="h-10 border border-input bg-background px-3 text-xs font-normal outline-none focus:border-steel-blue"/></label><label className="grid gap-1.5 text-[10px] font-bold">Status<select value={draft.status} onChange={(event) => setDraft({ ...draft, status: event.target.value })} className="h-10 border border-input bg-background px-3 text-xs font-normal outline-none focus:border-steel-blue">{["Pending", "In progress", "Approved", "Completed", "On hold"].map((item) => <option key={item}>{item}</option>)}</select></label></div><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setModal(null)}>Cancel</Button><Button type="submit" className="bg-industrial-orange text-primary-foreground hover:bg-industrial-orange/90">{modal === "create" ? "Create record" : "Save changes"}</Button></div></form></div>}</div>;
}
